-- StagePilot event operations core schema with row-level security.
create extension if not exists pgcrypto;
create table if not exists public.events (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null check(length(trim(name)) between 1 and 160), venue text not null default '', event_date date, timezone text not null default 'Asia/Kolkata', status text not null default 'draft' check(status in ('draft','published','archived')), plan_version integer not null default 1 check(plan_version>0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.event_members (event_id uuid not null references public.events(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null default 'crew' check(role in ('owner','manager','crew','viewer')), invited_at timestamptz not null default now(), primary key(event_id,user_id));
create table if not exists public.agenda_items (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, position integer not null check(position>=0), title text not null check(length(trim(title)) between 1 and 200), owner_name text not null default '', starts_at timestamptz not null, ends_at timestamptz not null, notes text not null default '', status text not null default 'planned' check(status in ('planned','ready','live','completed','cancelled')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(ends_at>starts_at), unique(event_id,position));
create table if not exists public.event_activity (id bigint generated always as identity primary key, event_id uuid not null references public.events(id) on delete cascade, actor_id uuid references auth.users(id) on delete set null, action text not null, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists events_owner_updated_idx on public.events(owner_id,updated_at desc);
create index if not exists event_members_user_idx on public.event_members(user_id,event_id);
create index if not exists agenda_event_position_idx on public.agenda_items(event_id,position);
create index if not exists activity_event_created_idx on public.event_activity(event_id,created_at desc);
create or replace function public.stagepilot_is_member(eid uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.event_members m where m.event_id=eid and m.user_id=auth.uid()) $$;
create or replace function public.stagepilot_is_owner(eid uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.events e where e.id=eid and e.owner_id=auth.uid()) $$;
revoke all on function public.stagepilot_is_member(uuid) from public; grant execute on function public.stagepilot_is_member(uuid) to authenticated;
revoke all on function public.stagepilot_is_owner(uuid) from public; grant execute on function public.stagepilot_is_owner(uuid) to authenticated;
alter table public.events enable row level security; alter table public.event_members enable row level security; alter table public.agenda_items enable row level security; alter table public.event_activity enable row level security;
drop policy if exists events_select_members on public.events; create policy events_select_members on public.events for select to authenticated using(owner_id=auth.uid() or public.stagepilot_is_member(id));
drop policy if exists events_insert_owner on public.events; create policy events_insert_owner on public.events for insert to authenticated with check(owner_id=auth.uid());
drop policy if exists events_update_owner on public.events; create policy events_update_owner on public.events for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
drop policy if exists events_delete_owner on public.events; create policy events_delete_owner on public.events for delete to authenticated using(owner_id=auth.uid());
drop policy if exists members_select_self_or_owner on public.event_members; create policy members_select_self_or_owner on public.event_members for select to authenticated using(user_id=auth.uid() or public.stagepilot_is_owner(event_id));
drop policy if exists members_owner_manage on public.event_members; create policy members_owner_manage on public.event_members for all to authenticated using(public.stagepilot_is_owner(event_id)) with check(public.stagepilot_is_owner(event_id));
drop policy if exists agenda_select_members on public.agenda_items; create policy agenda_select_members on public.agenda_items for select to authenticated using(public.stagepilot_is_owner(event_id) or public.stagepilot_is_member(event_id));
drop policy if exists agenda_manage_owner_manager on public.agenda_items; create policy agenda_manage_owner_manager on public.agenda_items for all to authenticated using(public.stagepilot_is_owner(agenda_items.event_id) or exists(select 1 from public.event_members m where m.event_id=agenda_items.event_id and m.user_id=auth.uid() and m.role in ('manager','owner'))) with check(public.stagepilot_is_owner(agenda_items.event_id) or exists(select 1 from public.event_members m where m.event_id=agenda_items.event_id and m.user_id=auth.uid() and m.role in ('manager','owner')));
drop policy if exists activity_select_members on public.event_activity; create policy activity_select_members on public.event_activity for select to authenticated using(public.stagepilot_is_owner(event_id) or public.stagepilot_is_member(event_id));
drop policy if exists activity_insert_members on public.event_activity; create policy activity_insert_members on public.event_activity for insert to authenticated with check((public.stagepilot_is_owner(event_id) or public.stagepilot_is_member(event_id)) and actor_id=auth.uid());
grant select,insert,update,delete on public.events,public.event_members,public.agenda_items to authenticated; grant select,insert on public.event_activity to authenticated; grant usage,select on sequence public.event_activity_id_seq to authenticated;
